SELECT length('gamma'), upper('gamma'), lower('gamma'), substr('gamma', 1, 3), instr('gamma', 'sigma'), replace('gamma', 'a', 'XY'), trim('gamma'), ltrim('gamma', 'ab'), hex('gamma'), quote('gamma'), unicode('gamma'), 'gamma' LIKE '%', 'gamma' GLOB '?', char(85, 788), 'gamma' || 'sigma', 'gamma' < 'sigma', 'gamma' = 'sigma' COLLATE NOCASE;
SELECT count(*), count(id), sum(id), total(id), avg(id), min(id), max(id), count(DISTINCT id) FROM t1 WHERE coalesce(c2 IS NULL, ref);
SELECT id, count(*), group_concat(id, ';') FROM (SELECT * FROM t1 ORDER BY id) GROUP BY id HAVING count(*) > 2 ORDER BY id;
